const express = require('express');
const path = require('path');
const app = express();

app.get('/', (req, res) => {
  const files = [
    { name: 'Bellevue_Bid_Takeoff.xlsx', desc: 'Full 60-item bid breakdown with quantities (4 tabs)' },
    { name: 'Bellevue_Schedules.xlsx', desc: 'Door schedule, finish schedule, materials legend (3 tabs)' },
    { name: 'Bellevue_Project_Summary.pdf', desc: 'Project overview and scope summary' },
    { name: 'Bellevue_Extraction_Summary.pdf', desc: 'What was extracted and key findings' },
    { name: 'Bellevue_MEP_Coordination.pdf', desc: 'MEP coordination review with conflict flags' }
  ];

  res.send(`<!DOCTYPE html>
<html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Bellevue Hospital — Project Exports</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e2e8f0;min-height:100vh;display:flex;align-items:center;justify-content:center}
.container{max-width:600px;width:100%;padding:40px 20px}
h1{font-size:1.5rem;color:#6366f1;margin-bottom:4px}
.sub{color:#64748b;font-size:.85rem;margin-bottom:32px}
.file{background:#12121a;border:1px solid #1e1e2e;border-radius:12px;padding:16px 20px;margin-bottom:12px;display:flex;align-items:center;gap:16px;text-decoration:none;color:#e2e8f0;transition:all .2s}
.file:hover{border-color:#6366f1;background:#1a1a2e;transform:translateY(-1px)}
.icon{font-size:1.5rem}
.info{flex:1}
.info .name{font-weight:600;font-size:.95rem}
.info .desc{color:#64748b;font-size:.8rem;margin-top:2px}
.dl{color:#6366f1;font-size:.85rem;font-weight:600}
</style></head><body>
<div class="container">
<h1>🏗️ HHC Bellevue Hospital</h1>
<p class="sub">Ambulance Drop Off Renovation — Project #11202402</p>
${files.map(f => `<a class="file" href="/download/${f.name}">
<span class="icon">${f.name.endsWith('.xlsx') ? '📊' : '📄'}</span>
<div class="info"><div class="name">${f.name}</div><div class="desc">${f.desc}</div></div>
<span class="dl">Download →</span></a>`).join('')}
</div></body></html>`);
});

app.get('/download/:file', (req, res) => {
  const allowed = ['Bellevue_Bid_Takeoff.xlsx','Bellevue_Schedules.xlsx','Bellevue_Project_Summary.pdf','Bellevue_Extraction_Summary.pdf','Bellevue_MEP_Coordination.pdf'];
  if (allowed.includes(req.params.file)) {
    res.download(path.join(__dirname, req.params.file));
  } else {
    res.status(404).send('Not found');
  }
});

app.listen(3970, () => console.log('Bellevue exports server on port 3970'));

