const http = require('http');
const fs = require('fs');
const path = require('path');
const dir = __dirname;
const s = http.createServer((req, res) => {
  const f = path.join(dir, req.url === '/' ? 'index.html' : req.url);
  fs.readFile(f, (e, d) => {
    if (e) { res.writeHead(404); res.end('Not found'); }
    else { res.writeHead(200); res.end(d); }
  });
});
s.listen(3980, () => console.log('Blueprint SaaS listening on 3980'));

